  nodeName:   { ansi: ['bold'],                md: 'bold' },
  nodeId:     { ansi: ['gray'],                md: 'none' },      // (14/16)
  coord:      { ansi: ['gray'],                md: 'none' },      // @(x,y)
  arrow:      { ansi: ['brightMagenta'],             md: 'none' },      // ->  <-  ~>  =
