  enumValue:  { ansi: ['brightCyan'],          md: 'none' },      // enum:5«Name»
  idValue:    { ansi: ['green'],               md: 'none' },      // id:123
  vector:     { ansi: ['cyan'],                md: 'none' },      // (1, 2, 3)
  // ---- references (refs) ----
