g = 2; // i2: corresponds to the parameter slot of the Kernel implementation\n\n  // Value and type\n  TypedValue value = 3;\n  int32      type  = 4; // Be careful! ServerTypeId in Server and ClientVarType in Client\n\n  // Connections\n  repeated NodeConnection connections = 5;\n\n  // Dynamic binding info\n\n  // Metadata binding\n  // Used by nodes such as SendSignal, stores the binding of an RPC ID or Topic Name\n  // Formerly signalPin\n  optional PinSignature binding_meta = 6;\n\n  // Persistent pin ID\n  // Only for dynamic types (Struct/Signal/Composite)\n  // When the Shell definition changes (pins inserted or reordered), this ID is used to recover the connections\n  optional int32 persistent_pin_uid = 7; // Formerly compositePinUid\n}\n\n// Connection\nmessage NodeConnection {\n  int32        target_node_index = 1;\n  PinSignature target_pin_shell  = 2;\n  PinSignature target_pin_kernel = 3;\n}\n\n// Interface mapping: pipes through the wall\nmessage InterfaceMapping {\n  // Pin definition on the shell of the composite node (outside)\n  PinSignature external_port = 1;\n\n  // Index of the inner target node it maps to (inside)\n  int32 internal_target_node_handle = 2;\n\n  // Concrete inner pin it maps to (logical/physical)\n  PinSignature internal_port_shell  = 3;\n  PinSignature internal_port_kernel = 4;\n}\n\n// Graph variable (blackboard variable)\nmessage GraphVariable {\n  string var_name = 2;\n\n  // Data type definition of the variable\n  ServerTypeId base_type = 3;\n\n  // Initial/current value of the variable\n  TypedValue storage_value = 4;\n\n  // Whether it is exposed as an externally configurable parameter\n  bool is_public = 5;\n\n  // For a struct variable, the ID of its definition\n  optional int64 schema_ref_id = 6;\n\n  // Sub-type definition of a container type (leftover field, only valid for Map)\n  ServerTypeId container_key_type   = 7;\n  ServerTypeId container_value_type = 8;\n}\n\n// Comment / text note\nmessage Annotation {\n  stri